#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: HQ setup. The steps only Yitzy can do: Google sign-in for /hq and the
# secrets the agents need. Nothing secret is written to this (public) repo: secrets go
# straight from hidden input into GitHub Actions secrets on the private agents repo.
# ══════════════════════════════════════════════════════════════════════════

TOTAL_STAGES=7
REF="rdtvwvylmkxpdbbnsmuu"
SUPA_URL="https://${REF}.supabase.co"
AGENTS_REPO="yitzybitzyspider/bitzy-hq-agents"

banner "HQ setup: sign-in and agent secrets"

stage "Google Cloud: create the OAuth client"
say "This lets you sign in to bitzyspider.com/hq with one tap. About five minutes."
open_url "https://console.cloud.google.com/apis/credentials"
step "Pick any personal project, or create one named bitzy-hq."
step "If asked to configure the consent screen: External, app name HQ, your email for both contacts."
step "Under Audience keep it in Testing and add yitzy305@gmail.com as the only test user."
step "Create Credentials, then OAuth client ID, type Web application, name HQ."
step "Authorized JavaScript origins: https://bitzyspider.com"
step "Authorized redirect URIs: ${SUPA_URL}/auth/v1/callback"
step "Click Create. Leave the dialog with the Client ID and Client secret open; you paste them in the next stage."
note "The client secret goes only into Supabase, never into this terminal."
pause

stage "Supabase: turn on the Google provider"
open_url "https://supabase.com/dashboard/project/${REF}/auth/providers"
step "Expand Google and switch it on."
step "Paste the Client ID and the Client secret from the Google dialog."
step "Save."
pause

stage "Supabase: allowed redirect URLs"
open_url "https://supabase.com/dashboard/project/${REF}/auth/url-configuration"
step "Site URL: https://bitzyspider.com/hq/"
step "Redirect URLs, add both: https://bitzyspider.com/hq/  and  http://localhost:4319/hq/"
step "Save."
pause

stage "Check: sign in for real"
open_url "https://bitzyspider.com/hq/"
step "Tap Sign in with Google and pick yitzy305@gmail.com."
step "You should land on the deck saying Deck clear (no collectors have run yet)."
note "If Google says access blocked, the test user in stage 1 is missing."
note "If you bounce back to the sign-in button, a redirect URL in stage 3 does not match exactly."
if confirm "Did you land on the deck?"; then
  say "Sign-in works. Issue #69 can be closed."
else
  SKIPPED+=("Google sign-in did not complete: recheck stages 1 to 3, then rerun this wizard")
  warn "Carrying on with the agent secrets; rerun the wizard later for sign-in."
fi
pause

stage "Supabase service key, into the private agents repo"
say "Agents write cards with this key. It bypasses row security, so it only ever lives"
say "as a GitHub Actions secret on ${AGENTS_REPO} (and later on the box)."
open_url "https://supabase.com/dashboard/project/${REF}/settings/api-keys"
step "Find the service_role key. If the page has a Legacy API keys tab, it is there. Reveal and copy it."
note "I am not certain of the current tab names on this page. You want the key labeled service_role, not anon and not publishable."
ask_secret SUPABASE_SERVICE_KEY "Paste the service_role key (input hidden):"
export GH_REPO="$AGENTS_REPO"
if [[ -n "${SUPABASE_SERVICE_KEY}" ]]; then
  set_secret SUPABASE_SERVICE_KEY "$SUPABASE_SERVICE_KEY"
  set_secret SUPABASE_URL "$SUPA_URL"
else
  SKIPPED+=("GitHub secret SUPABASE_SERVICE_KEY on ${AGENTS_REPO}")
  warn "Nothing pasted; skipped."
fi
unset SUPABASE_SERVICE_KEY
pause

stage "Anthropic API key for the reviser"
say "The reviser makes one Claude call each time you send a card back with a note."
open_url "https://console.anthropic.com/settings/keys"
step "Create a key named bitzy-hq-reviser so its spend shows up on its own line."
step "Copy it now; it is shown once."
ask_secret ANTHROPIC_API_KEY "Paste the Anthropic API key (input hidden):"
if [[ -n "${ANTHROPIC_API_KEY}" ]]; then
  set_secret ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
else
  SKIPPED+=("GitHub secret ANTHROPIC_API_KEY on ${AGENTS_REPO}")
  warn "Nothing pasted; skipped."
fi
unset ANTHROPIC_API_KEY
pause

stage "Check: run the reviser once"
say "This runs the reviser workflow by hand. With nothing sent back yet it should say: nothing waiting."
if gh workflow view reviser.yml --repo "$AGENTS_REPO" >/dev/null 2>&1; then
  if confirm "Run it now?"; then
    if gh workflow run reviser.yml --repo "$AGENTS_REPO" >/dev/null 2>&1; then
      say "Started. Waiting a few seconds for the run to register."
      sleep 8
      run_id=$(gh run list --repo "$AGENTS_REPO" --workflow reviser.yml --limit 1 --json databaseId --jq '.[0].databaseId' 2>/dev/null || true)
      if [[ -n "${run_id:-}" ]] && gh run watch "$run_id" --repo "$AGENTS_REPO" --exit-status >/dev/null 2>&1; then
        gh run view "$run_id" --repo "$AGENTS_REPO" --log 2>/dev/null | grep -E "reviser done|Secrets are not set|Supabase [0-9]+" | tail -n 3 || true
        say "Reviser run finished cleanly."
      else
        SKIPPED+=("Reviser run failed or could not be watched: gh run list --repo ${AGENTS_REPO} --workflow reviser.yml")
        warn "The run did not finish cleanly. See the run log."
      fi
    else
      SKIPPED+=("Could not start reviser.yml on ${AGENTS_REPO}")
      warn "Could not start the workflow."
    fi
  fi
else
  SKIPPED+=("Merge the reviser PR first: https://github.com/${AGENTS_REPO}/pull/1 , then: gh workflow run reviser.yml --repo ${AGENTS_REPO}")
  warn "The reviser workflow is not on the default branch yet (its PR is still open)."
fi
unset GH_REPO

finish
